// Cours « Lire l’arabe » (généré par lire_build.py)
const ALPHA=[["ا","alif","a long (â)",1,"أنا","ana","je, moi",1200,32],["ب","ba","b",0,"بابا","baba","papa, mon père",1201,97],["ت","ta","t",0,"تمر","tmer","dattes",1202,237],["ث","tha","th anglais (souvent t)",0,"ثوم","thoum","ail",1203,221],["ج","jim","j, dj",0,"جدّي","jeddi","mon grand-père",1204,100],["ح","7a","h soufflé (7)",0,"حليب","7lib","lait",1205,249],["خ","kha","kh",0,"خبز","khobz","pain",1206,10],["د","dal","d",1,"دار","dar","maison",1207,57],["ذ","dhal","th de « this » (souvent d)",1,"ذراع","dra3","le bras",1208,128],["ر","ra","r roulé",1,"راس","ras","la tête",1209,117],["ز","zay","z",1,"زوج","zouj","2",1210,62],["س","sin","s",0,"سلام","salam","salut, bonjour",1211,1],["ش","chin","ch",0,"شمس","chems","soleil",1212,9],["ص","sad","s appuyé",0,"الصباح","es-sba7","le matin",1213,83],["ض","dad","d appuyé",0,"ضو","dhaw","lumière, électricité",1214,201],["ط","ta","t appuyé",0,"الطريق","et-trig","la route",1215,1035],["ظ","dha","dh appuyé (souvent d)",0,"ظهر","dhar","le dos",1216,134],["ع","3ayn","3 (gorge serrée)",0,"عين","3in","l’œil",1217,120],["غ","ghayn","gh",0,"غالي","ghali","cher",1218,11],["ف","fa","f",0,"فم","fem","la bouche",1219,123],["ق","qaf","q (ou g)",0,"قلب","qalb","le cœur",1220,132],["ك","kaf","k",0,"كتاب","ktab","livre",1221,15],["ل","lam","l",0,"الليل","el-lil","la nuit",1222,86],["م","mim","m",0,"مدرسة","madrasa","école",1223,58],["ن","noun","n",0,"النهار","en-nhar","le jour, la journée",1224,87],["ه","ha","h léger",0,"هو","houwa","il",1225,35],["و","waw","w, ou",1,"ولد","weld","garçon",1226,55],["ي","ya","y, i",0,"يمّا","yemma","maman, ma mère",1227,96]];
const LES=[{"id":"r0","e":"🧭","n":"Comment marche l’écriture arabe","goal":"comprendre les 5 règles de base avant de lire ta première lettre.","h":"<div class=\"card\"><h3><span class=\"n\">1</span>De droite à gauche</h3><p>L’arabe s’écrit et se lit <b>de droite à gauche</b>. Un livre arabe s’ouvre donc « à l’envers » pour un francophone.</p><div class=\"rtl-demo\"><span lang=\"ar\">كَتَبَ</span><i aria-hidden=\"true\">← lecture</i></div><p>Ce mot se lit <b>ka-ta-ba</b> (« il a écrit ») : on commence par la lettre la plus à droite.</p></div><div class=\"card\"><h3><span class=\"n\">2</span>On écrit surtout les consonnes</h3><p>L’alphabet compte <b>28 lettres</b>, presque toutes des consonnes. Il n’y a pas de majuscules.</p><p>Les <b>voyelles courtes</b> (a, i, ou) ne sont pas des lettres : ce sont de <b>petits signes</b> posés au-dessus ou au-dessous de la consonne.</p><div class=\"hxs\"><div class=\"hx\"><span lang=\"ar\">كَ</span><small>ka</small></div><div class=\"hx\"><span lang=\"ar\">كِ</span><small>ki</small></div><div class=\"hx\"><span lang=\"ar\">كُ</span><small>kou</small></div></div><p>Dans les livres pour enfants, le Coran et ce cours, ces signes sont écrits. Dans les journaux, sur les panneaux et sur un téléphone, on les <b>omet</b> : c’est l’objet de la leçon 13.</p></div><div class=\"card\"><h3><span class=\"n\">3</span>Les lettres s’attachent</h3><p>Dans un mot, les lettres se <b>lient</b> entre elles comme en écriture cursive. Chaque lettre change un peu de forme selon sa place : <b>isolée, début, milieu, fin</b>.</p><div class=\"hxs\"><div class=\"hx\"><span lang=\"ar\">ك</span><small>isolée</small></div><div class=\"hx\"><span lang=\"ar\">كـ</span><small>début</small></div><div class=\"hx\"><span lang=\"ar\">ـكـ</span><small>milieu</small></div><div class=\"hx\"><span lang=\"ar\">ـك</span><small>fin</small></div></div><p>Bonne nouvelle : la forme change, mais le « squelette » reste reconnaissable.</p></div><div class=\"card\"><h3><span class=\"n\">4</span>Six lettres ne s’attachent pas à la suivante</h3><p>Les lettres <span lang=\"ar\" class=\"ari\">ا د ذ ر ز و</span> s’attachent à la lettre d’avant, jamais à celle d’après. Elles créent des « trous » dans le mot :</p><div class=\"hxs\"><div class=\"hx\"><span lang=\"ar\">وَزِير</span><small>wazîr : 3 morceaux</small></div></div><p>Ce n’est pas une fin de mot, c’est juste une lettre qui ne tend pas la main à gauche.</p></div><div class=\"card\"><h3><span class=\"n\">5</span>Les points font la différence</h3><p>Beaucoup de lettres ont <b>la même forme</b> et ne se distinguent que par leurs <b>points</b> : leur nombre et leur position (dessus ou dessous).</p><div class=\"hxs\"><div class=\"hx\"><span lang=\"ar\">ب</span><small>b : 1 dessous</small></div><div class=\"hx\"><span lang=\"ar\">ت</span><small>t : 2 dessus</small></div><div class=\"hx\"><span lang=\"ar\">ث</span><small>th : 3 dessus</small></div></div><p>C’est pour ça que ce cours présente les lettres <b>par familles de formes</b>, et pas dans l’ordre de l’alphabet.</p><p class=\"tip\">💡 Pour lire, regarde dans cet ordre : la forme, puis les points, puis le petit signe de voyelle.</p></div>","read":[{"ar":"كَتَبَ","tr":"ka-ta-ba","fr":"il a écrit","a":0,"v":"كَتَبَ","dz":0}],"q":[{"t":"qcm","q":"Dans quel sens se lit l’arabe ?","o":["De droite à gauche","De gauche à droite","De haut en bas"],"c":0,"ex":""},{"t":"qcm","q":"Combien de lettres compte l’alphabet arabe ?","o":["28","26","32"],"c":0,"ex":""},{"t":"qcm","q":"Comment écrit-on les voyelles courtes (a, i, ou) ?","o":["Avec de petits signes au-dessus ou au-dessous de la lettre","Avec des lettres, comme en français","On ne peut pas les écrire"],"c":0,"ex":""},{"t":"qcm","q":"Combien de formes une lettre peut-elle prendre ?","o":["Jusqu’à 4 : isolée, début, milieu, fin","Une seule","Deux : majuscule et minuscule"],"c":0,"ex":""},{"t":"qcm","q":"Qu’est-ce qui distingue ب, ت et ث ?","o":["Leurs points","Leur taille","Leur hauteur sur la ligne"],"c":0,"ex":"","big":"ب ت ث"},{"t":"qcm","q":"Dans وَزِير, pourquoi le mot est-il coupé en morceaux ?","o":["Certaines lettres ne s’attachent pas à la suivante","Ce sont trois mots différents","C’est une faute d’écriture"],"c":0,"ex":"","big":"وَزِير"},{"t":"ass","ar":"كَتَبَ","tr":"ka-ta-ba","fr":"il a écrit","q":"Écris « kataba » (il a écrit) : touche les lettres dans l’ordre de lecture"}]},{"id":"r1","e":"✏️","n":"Les voyelles courtes avec ب ت ث","L":"بتث","goal":"lire tes premières syllabes : ba, bi, bou, ta, ti, tou…","h":"<div class=\"card\"><h3><span class=\"n\">1</span>Trois petits signes, trois sons</h3><p>Une voyelle courte se pose sur la consonne qui la précède. On lit toujours <b>consonne + voyelle</b>.</p><table class=\"hk\"><tr><th>Signe</th><th>Nom</th><th>Son</th><th>Exemple</th></tr><tr><td lang=\"ar\" class=\"ari\">ـَ</td><td>fat7a, petit trait <b>au-dessus</b></td><td><b>a</b></td><td lang=\"ar\" class=\"ari\">بَ = ba</td></tr><tr><td lang=\"ar\" class=\"ari\">ـِ</td><td>kasra, petit trait <b>au-dessous</b></td><td><b>i</b></td><td lang=\"ar\" class=\"ari\">بِ = bi</td></tr><tr><td lang=\"ar\" class=\"ari\">ـُ</td><td>damma, petit <b>crochet</b> au-dessus</td><td><b>ou</b></td><td lang=\"ar\" class=\"ari\">بُ = bou</td></tr></table><p class=\"tip\">💡 Moyen mnémotechnique : le trait <b>en haut</b> fait « a » (bouche ouverte vers le haut), le trait <b>en bas</b> fait « i » (sourire), le crochet fait « ou » (bouche ronde).</p></div><div class=\"card\"><h3><span class=\"n\">2</span>La famille ب ت ث</h3><p>Même forme de « barque », seuls les points changent. Écoute le nom de chaque lettre.</p>%LETTERS%</div><div class=\"card\"><h3><span class=\"n\">3</span>Lecture guidée</h3><p>Lis chaque syllabe à voix haute, puis utilise les aides pour vérifier.</p>%READ%</div>","read":[{"ar":"بَ","tr":"ba","fr":"","a":0,"v":"بَ","dz":0},{"ar":"بِ","tr":"bi","fr":"","a":0,"v":"بِ","dz":0},{"ar":"بُ","tr":"bou","fr":"","a":0,"v":"بُ","dz":0},{"ar":"تَ","tr":"ta","fr":"","a":0,"v":"تَ","dz":0},{"ar":"تِ","tr":"ti","fr":"","a":0,"v":"تِ","dz":0},{"ar":"تُ","tr":"tou","fr":"","a":0,"v":"تُ","dz":0},{"ar":"ثَ","tr":"tha","fr":"","a":0,"v":"ثَ","dz":0},{"ar":"ثِ","tr":"thi","fr":"","a":0,"v":"ثِ","dz":0},{"ar":"ثُ","tr":"thou","fr":"","a":0,"v":"ثُ","dz":0},{"ar":"بَتَ","tr":"ba-ta","fr":"","a":0,"v":"بَتَ","dz":0},{"ar":"تُبِ","tr":"tou-bi","fr":"","a":0,"v":"تُبِ","dz":0},{"ar":"ثَبَتَ","tr":"tha-ba-ta","fr":"il est resté ferme","a":0,"v":"ثَبَتَ","dz":0}],"q":[{"t":"qcm","q":"Comment se lit cette syllabe ?","o":["bi","ba","bou"],"c":0,"ex":"","big":"بِ"},{"t":"qcm","q":"Comment se lit cette syllabe ?","o":["tou","ta","ti"],"c":0,"ex":"","big":"تُ"},{"t":"qcm","q":"Quelle écriture se lit « tha » ?","o":["ثَ","تَ","ثِ"],"c":0,"ex":"","arO":1},{"t":"qcm","q":"Écoute le nom de la lettre. Laquelle est-ce ?","o":["ب","ت","ث"],"c":0,"ex":"","arO":1,"a":1201},{"t":"qcm","q":"Quelle lettre a trois points ?","o":["ث","ت","ب"],"c":0,"ex":"","arO":1},{"t":"qcm","q":"Un petit trait <b>sous</b> la lettre donne le son…","o":["i","a","ou"],"c":0,"ex":""},{"t":"lis","w":{"ar":"ثَبَتَ","tr":"tha-ba-ta","fr":"il est resté ferme","a":0,"v":"ثَبَتَ","dz":0},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"تُبِ","tr":"tou-bi","fr":"","a":0,"v":"تُبِ","dz":0},"q":"Lis ce mot à voix haute"}]},{"id":"r2","e":"📏","n":"Les voyelles longues : ا و ي","L":"اوي","goal":"lire les sons longs â, î, oû et tes premiers vrais mots.","h":"<div class=\"card\"><h3><span class=\"n\">1</span>Allonger une voyelle</h3><p>Pour faire une voyelle <b>longue</b>, on ajoute une lettre après la voyelle courte du même son :</p><table class=\"hk\"><tr><th>Court</th><th>Long</th><th>Son long</th></tr><tr><td lang=\"ar\" class=\"ari\">بَ ba</td><td lang=\"ar\" class=\"ari\">بَا</td><td><b>bâ</b> : fat7a + alif ا</td></tr><tr><td lang=\"ar\" class=\"ari\">بِ bi</td><td lang=\"ar\" class=\"ari\">بِي</td><td><b>bî</b> : kasra + ya ي</td></tr><tr><td lang=\"ar\" class=\"ari\">بُ bou</td><td lang=\"ar\" class=\"ari\">بُو</td><td><b>boû</b> : damma + waw و</td></tr></table><p>Dans ce cours, l’accent circonflexe (â, î, oû) signale un son long : on le tient deux fois plus longtemps.</p></div><div class=\"card\"><h3><span class=\"n\">2</span>Les lettres ا و ي</h3><p>و et ي ont deux rôles : <b>voyelle longue</b> (oû, î) après la voyelle du même son, ou <b>consonne</b> (w, y) quand elles portent elles-mêmes une voyelle : <span lang=\"ar\" class=\"ari\">وَ</span> = wa, <span lang=\"ar\" class=\"ari\">يَ</span> = ya. L’alif ا ne s’attache jamais à la lettre suivante.</p>%LETTERS%</div><div class=\"card\"><h3><span class=\"n\">3</span>La dernière lettre</h3><p>Souvent, la dernière lettre d’un mot ne porte <b>aucun signe</b> : on s’arrête simplement sur la consonne. <span lang=\"ar\" class=\"ari\">بَاب</span> se lit <b>bâb</b>, pas « bâba ».</p></div><div class=\"card\"><h3><span class=\"n\">4</span>Lecture guidée</h3>%READ%</div>","read":[{"ar":"بَا","tr":"bâ","fr":"","a":0,"v":"بَا","dz":0},{"ar":"بِي","tr":"bî","fr":"","a":0,"v":"بِي","dz":0},{"ar":"بُو","tr":"boû","fr":"","a":0,"v":"بُو","dz":0},{"ar":"تَا","tr":"tâ","fr":"","a":0,"v":"تَا","dz":0},{"ar":"تِي","tr":"tî","fr":"","a":0,"v":"تِي","dz":0},{"ar":"تُو","tr":"toû","fr":"","a":0,"v":"تُو","dz":0},{"ar":"بَاب","tr":"bâb","fr":"porte","a":0,"v":"بَاب","dz":0},{"ar":"بَابَا","tr":"bâ-bâ","fr":"papa","a":0,"v":"بَابَا","dz":0},{"ar":"تُوت","tr":"toût","fr":"mûres","a":0,"v":"تُوت","dz":0},{"ar":"ثَابِت","tr":"thâ-bit","fr":"stable, fixe","a":0,"v":"ثَابِت","dz":0}],"q":[{"t":"qcm","q":"Comment se lit cette syllabe ?","o":["boû","bou","bî"],"c":0,"ex":"","big":"بُو"},{"t":"qcm","q":"Quelle écriture se lit « bî » ?","o":["بِي","بِ","بَا"],"c":0,"ex":"","arO":1},{"t":"qcm","q":"Comment se lit ce mot ?","o":["bâb","bâba","bab"],"c":0,"ex":"La dernière lettre ne porte pas de voyelle : on s’arrête sur le b.","big":"بَاب"},{"t":"qcm","q":"Dans يَ, la lettre ي est…","o":["une consonne : ya","une voyelle longue : î","muette"],"c":0,"ex":"","big":"يَ"},{"t":"qcm","q":"Écoute le nom de la lettre. Laquelle est-ce ?","o":["و","ي","ا"],"c":0,"ex":"","arO":1,"a":1226},{"t":"lis","w":{"ar":"تُوت","tr":"toût","fr":"mûres","a":0,"v":"تُوت","dz":0},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"ثَابِت","tr":"thâ-bit","fr":"stable, fixe","a":0,"v":"ثَابِت","dz":0},"q":"Lis ce mot à voix haute"},{"t":"ass","ar":"بَاب","tr":"bâb","fr":"porte","q":"Écris « bâb » (porte) : touche les lettres dans l’ordre de lecture"}]},{"id":"r3","e":"⛔","n":"Les lettres qui ne s’attachent pas : د ذ ر ز","L":"دذرز","goal":"repérer les « trous » dans les mots et lire د ذ ر ز.","h":"<div class=\"card\"><h3><span class=\"n\">1</span>Deux paires</h3><p><b>د</b> (d) et <b>ذ</b> (dh, comme le « th » anglais de <i>this</i>) : un petit angle. <b>ر</b> (r roulé) et <b>ز</b> (z) : une petite virgule qui descend sous la ligne. Dans chaque paire, seul le point change.</p><p>Comme ا et و, ces quatre lettres <b>ne s’attachent jamais à la lettre suivante</b>. Une lettre qui vient après elles prend la forme du début.</p>%LETTERS%</div><div class=\"card\"><h3><span class=\"n\">2</span>Lecture guidée</h3><p>Repère les trous dans chaque mot avant de le lire.</p>%READ%</div>","read":[{"ar":"دَار","tr":"dâr","fr":"maison","a":0,"v":"دَار","dz":0},{"ar":"بَارِد","tr":"bâ-rid","fr":"froid","a":0,"v":"بَارِد","dz":0},{"ar":"بَرِيد","tr":"ba-rîd","fr":"courrier, poste","a":0,"v":"بَرِيد","dz":0},{"ar":"وَزِير","tr":"wa-zîr","fr":"ministre","a":0,"v":"وَزِير","dz":0},{"ar":"تُرَاب","tr":"tou-râb","fr":"terre, poussière","a":0,"v":"تُرَاب","dz":0},{"ar":"ذَابَ","tr":"dhâ-ba","fr":"il a fondu","a":0,"v":"ذَابَ","dz":0},{"ar":"زَارَ","tr":"zâ-ra","fr":"il a rendu visite","a":0,"v":"زَارَ","dz":0}],"q":[{"t":"tri","q":"Range chaque lettre : s’attache-t-elle à la lettre suivante ?","cats":["S’attache","Ne s’attache pas"],"it":[["ب",0],["د",1],["ت",0],["ر",1],["ي",0],["ا",1],["ز",1],["ث",0],["و",1]]},{"t":"qcm","q":"Quel son fait cette lettre ?","o":["dh, comme « this » en anglais","z","d"],"c":0,"ex":"","big":"ذ"},{"t":"qcm","q":"Écoute le nom de la lettre. Laquelle est-ce ?","o":["ر","ز","د"],"c":0,"ex":"","arO":1,"a":1209},{"t":"qcm","q":"Que veut dire ce mot ?","o":["courrier, poste","froid","maison"],"c":0,"ex":"","big":"بَرِيد"},{"t":"lis","w":{"ar":"وَزِير","tr":"wa-zîr","fr":"ministre","a":0,"v":"وَزِير","dz":0},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"بَارِد","tr":"bâ-rid","fr":"froid","a":0,"v":"بَارِد","dz":0},"q":"Lis ce mot à voix haute"},{"t":"ass","ar":"دَار","tr":"dâr","fr":"maison","q":"Écris « dâr » (maison) : touche les lettres dans l’ordre de lecture"}]},{"id":"r4","e":"🌀","n":"La famille ج ح خ","L":"جحخ","goal":"distinguer j, 7 et kh, trois lettres de même forme.","h":"<div class=\"card\"><h3><span class=\"n\">1</span>Une forme, trois lettres</h3><p>Même crochet, le point fait tout : <b>ج</b> un point <b>dessous</b> (j), <b>ح</b> <b>sans point</b> (7), <b>خ</b> un point <b>dessus</b> (kh).</p><p><b>ح</b> n’existe pas en français : c’est un h <b>soufflé</b>, comme quand on souffle sur des lunettes pour les nettoyer. On l’écrit <b>7</b>, comme dans le cours de darija. <b>خ</b> se prononce comme la jota espagnole ou le « ch » allemand de <i>Bach</i>.</p>%LETTERS%</div><div class=\"card\"><h3><span class=\"n\">2</span>Lecture guidée</h3>%READ%</div>","read":[{"ar":"جَار","tr":"jâr","fr":"voisin","a":0,"v":"جَار","dz":0},{"ar":"جَدِيد","tr":"ja-dîd","fr":"nouveau","a":0,"v":"جَدِيد","dz":0},{"ar":"حَبِيب","tr":"7a-bîb","fr":"chéri, aimé","a":0,"v":"حَبِيب","dz":0},{"ar":"حَرِير","tr":"7a-rîr","fr":"soie","a":0,"v":"حَرِير","dz":0},{"ar":"خَبِير","tr":"kha-bîr","fr":"expert","a":0,"v":"خَبِير","dz":0},{"ar":"تَاجِر","tr":"tâ-jir","fr":"commerçant","a":0,"v":"تَاجِر","dz":0}],"q":[{"t":"qcm","q":"Où est le point de la lettre خ ?","o":["Au-dessus","Au-dessous","Elle n’a pas de point"],"c":0,"ex":"","big":"خ"},{"t":"qcm","q":"Comment se lit cette syllabe ?","o":["7a","kha","ja"],"c":0,"ex":"","big":"حَ"},{"t":"qcm","q":"Quelle écriture se lit « kha » ?","o":["خَ","حَ","جَ"],"c":0,"ex":"","arO":1},{"t":"qcm","q":"Écoute le nom de la lettre. Laquelle est-ce ?","o":["ج","ح","خ"],"c":0,"ex":"","arO":1,"a":1204},{"t":"qcm","q":"Que veut dire ce mot ?","o":["commerçant","voisin","expert"],"c":0,"ex":"","big":"تَاجِر"},{"t":"lis","w":{"ar":"حَبِيب","tr":"7a-bîb","fr":"chéri, aimé","a":0,"v":"حَبِيب","dz":0},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"خَبِير","tr":"kha-bîr","fr":"expert","a":0,"v":"خَبِير","dz":0},"q":"Lis ce mot à voix haute"},{"t":"ass","ar":"جَدِيد","tr":"ja-dîd","fr":"nouveau","q":"Écris « jadîd » (nouveau) : touche les lettres dans l’ordre de lecture"}]},{"id":"r5","e":"🌊","n":"Les dents et les boucles : س ش ص ض","L":"سشصض","goal":"lire s, ch et les deux premières lettres « appuyées » ṣ et ḍ.","h":"<div class=\"card\"><h3><span class=\"n\">1</span>س et ش : trois petites dents</h3><p><b>س</b> (s) et <b>ش</b> (ch, comme dans « chat ») ont trois petites dents. ش porte trois points dessus.</p></div><div class=\"card\"><h3><span class=\"n\">2</span>ص et ض : les lettres appuyées</h3><p><b>ص</b> et <b>ض</b> ont une boucle. Ce sont des lettres <b>emphatiques</b> : on les prononce avec la langue plus en arrière et la bouche plus ronde, ce qui donne un son plus grave. Les voyelles autour sonnent aussi plus sourdes.</p><p>Dans ce cours, on les note avec un point dessous : <b>ṣ</b> pour ص, <b>ḍ</b> pour ض. Ainsi <span lang=\"ar\" class=\"ari\">سَ</span> = sa mais <span lang=\"ar\" class=\"ari\">صَ</span> = ṣa.</p>%LETTERS%</div><div class=\"card\"><h3><span class=\"n\">3</span>Lecture guidée</h3>%READ%</div>","read":[{"ar":"سَرِير","tr":"sa-rîr","fr":"lit","a":0,"v":"سَرِير","dz":0},{"ar":"شَرَاب","tr":"cha-râb","fr":"boisson","a":0,"v":"شَرَاب","dz":0},{"ar":"صَبَاح","tr":"ṣa-bâ7","fr":"matin","a":0,"v":"صَبَاح","dz":0},{"ar":"صَحِيح","tr":"ṣa-7î7","fr":"juste, correct","a":0,"v":"صَحِيح","dz":0},{"ar":"ضَبَاب","tr":"ḍa-bâb","fr":"brouillard","a":0,"v":"ضَبَاب","dz":0},{"ar":"بَارِيس","tr":"bâ-rîs","fr":"Paris","a":0,"v":"بَارِيس","dz":0}],"q":[{"t":"qcm","q":"Comment se lit cette syllabe ?","o":["cha","sa","ṣa"],"c":0,"ex":"","big":"شَ"},{"t":"qcm","q":"Laquelle de ces lettres est « appuyée » (son plus grave) ?","o":["ص","س","ش"],"c":0,"ex":"","arO":1},{"t":"qcm","q":"Quelle écriture se lit « ḍa » ?","o":["ضَ","صَ","دَ"],"c":0,"ex":"","arO":1},{"t":"qcm","q":"Écoute le nom de la lettre. Laquelle est-ce ?","o":["ش","س","ص"],"c":0,"ex":"","arO":1,"a":1212},{"t":"qcm","q":"Que veut dire ce mot ?","o":["brouillard","matin","boisson"],"c":0,"ex":"","big":"ضَبَاب"},{"t":"lis","w":{"ar":"بَارِيس","tr":"bâ-rîs","fr":"Paris","a":0,"v":"بَارِيس","dz":0},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"صَبَاح","tr":"ṣa-bâ7","fr":"matin","a":0,"v":"صَبَاح","dz":0},"q":"Lis ce mot à voix haute"},{"t":"ass","ar":"سَرِير","tr":"sa-rîr","fr":"lit","q":"Écris « sarîr » (lit) : touche les lettres dans l’ordre de lecture"}]},{"id":"r6","e":"🦒","n":"Les sons de gorge : ط ظ ع غ","L":"طظعغ","goal":"lire ṭ, ẓ et les deux lettres sans équivalent français : 3 et gh.","h":"<div class=\"card\"><h3><span class=\"n\">1</span>ط et ظ</h3><p>Une boucle avec un grand trait vertical. <b>ط</b> = t appuyé (<b>ṭ</b>), <b>ظ</b> = dh appuyé (<b>ẓ</b>), avec un point. Elles sont emphatiques, comme ص et ض.</p></div><div class=\"card\"><h3><span class=\"n\">2</span>ع et غ</h3><p><b>ع</b> (3ayn) se prononce au fond de la gorge, gorge serrée, comme un « a » étranglé. On l’écrit <b>3</b>, comme dans le cours de darija. <b>غ</b> (gh) est un r grasseyé, comme le r parisien de « Paris ».</p><p>Attention, ع change beaucoup de forme : <span lang=\"ar\" class=\"ari\">ع عـ ـعـ ـع</span>.</p>%LETTERS%</div><div class=\"card\"><h3><span class=\"n\">3</span>Lecture guidée</h3>%READ%</div>","read":[{"ar":"طَبِيب","tr":"ṭa-bîb","fr":"médecin","a":0,"v":"طَبِيب","dz":0},{"ar":"عِيد","tr":"3îd","fr":"fête","a":0,"v":"عِيد","dz":0},{"ar":"سَعِيد","tr":"sa-3îd","fr":"heureux","a":0,"v":"سَعِيد","dz":0},{"ar":"عَصِير","tr":"3a-ṣîr","fr":"jus","a":0,"v":"عَصِير","dz":0},{"ar":"غَرِيب","tr":"gha-rîb","fr":"étrange, étranger","a":0,"v":"غَرِيب","dz":0},{"ar":"عَرَبِي","tr":"3a-ra-bî","fr":"arabe","a":0,"v":"عَرَبِي","dz":0}],"q":[{"t":"qcm","q":"Comment se lit cette syllabe ?","o":["3i","ghi","ṭi"],"c":0,"ex":"","big":"عِ"},{"t":"qcm","q":"Quelle écriture se lit « gha » ?","o":["غَ","عَ","خَ"],"c":0,"ex":"","arO":1},{"t":"qcm","q":"Écoute le nom de la lettre. Laquelle est-ce ?","o":["ع","غ","ط"],"c":0,"ex":"","arO":1,"a":1217},{"t":"tri","q":"Ces lettres ont-elles un point ?","cats":["Un point","Pas de point"],"it":[["غ",0],["ع",1],["ظ",0],["ط",1],["خ",0],["ح",1],["ض",0],["ص",1]]},{"t":"qcm","q":"Que veut dire ce mot ?","o":["heureux","médecin","fête"],"c":0,"ex":"","big":"سَعِيد"},{"t":"lis","w":{"ar":"طَبِيب","tr":"ṭa-bîb","fr":"médecin","a":0,"v":"طَبِيب","dz":0},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"عَرَبِي","tr":"3a-ra-bî","fr":"arabe","a":0,"v":"عَرَبِي","dz":0},"q":"Lis ce mot à voix haute"},{"t":"ass","ar":"عِيد","tr":"3îd","fr":"fête","q":"Écris « 3îd » (fête) : touche les lettres dans l’ordre de lecture"}]},{"id":"r7","e":"🧩","n":"Les dernières lettres : ف ق ك ل م ن ه","L":"فقكلمنه","goal":"connaître les 28 lettres et lire la ligature لا.","h":"<div class=\"card\"><h3><span class=\"n\">1</span>Sept lettres</h3><ul><li><b>ف</b> (f) : une boucle et <b>un</b> point dessus. <b>ق</b> (q) : une boucle plus profonde et <b>deux</b> points. Le q se prononce au fond de la gorge (en darija, souvent g).</li><li><b>ك</b> (k), <b>ل</b> (l) : une grande hampe. Au début du mot, ل ressemble à un grand trait : <span lang=\"ar\" class=\"ari\">لـ</span>.</li><li><b>م</b> (m) : une petite boule. <b>ن</b> (n) : une coupe avec un point.</li><li><b>ه</b> (h léger, comme en anglais) : la lettre qui change le plus de forme : <span lang=\"ar\" class=\"ari\">ه هـ ـهـ ـه</span>.</li></ul>%LETTERS%</div><div class=\"card\"><h3><span class=\"n\">2</span>La ligature لا</h3><p>Quand ل est suivi de ا, les deux lettres se croisent : ل + ا = <span lang=\"ar\" class=\"ari\">لا</span>. Elle se lit <b>lâ</b> et veut dire « non ».</p></div><div class=\"card\"><h3><span class=\"n\">3</span>Lecture guidée</h3>%READ%</div>","read":[{"ar":"قَلَم","tr":"qa-lam","fr":"stylo","a":0,"v":"قَلَم","dz":0},{"ar":"كِتَاب","tr":"ki-tâb","fr":"livre","a":0,"v":"كِتَاب","dz":0},{"ar":"فِيل","tr":"fîl","fr":"éléphant","a":0,"v":"فِيل","dz":0},{"ar":"نُور","tr":"noûr","fr":"lumière","a":0,"v":"نُور","dz":0},{"ar":"وَلَد","tr":"wa-lad","fr":"garçon","a":0,"v":"وَلَد","dz":0},{"ar":"هُنَا","tr":"hou-nâ","fr":"ici","a":0,"v":"هُنَا","dz":0},{"ar":"سَمَك","tr":"sa-mak","fr":"poisson","a":0,"v":"سَمَك","dz":0},{"ar":"قَمَر","tr":"qa-mar","fr":"lune","a":0,"v":"قَمَر","dz":0},{"ar":"لَا","tr":"lâ","fr":"non","a":0,"v":"لَا","dz":0}],"q":[{"t":"qcm","q":"Laquelle de ces deux lettres a deux points ?","o":["ق","ف"],"c":0,"ex":"","arO":1},{"t":"qcm","q":"Comment se lit ce mot ?","o":["lâ","al","la-a"],"c":0,"ex":"ل + ا forment la ligature لا.","big":"لَا"},{"t":"qcm","q":"Ces formes ـهـ هـ ـه sont…","o":["la même lettre ه","trois lettres différentes","des voyelles"],"c":0,"ex":""},{"t":"qcm","q":"Quelle écriture se lit « noûr » ?","o":["نُور","نَار","بُور"],"c":0,"ex":"","arO":1},{"t":"qcm","q":"Écoute le nom de la lettre. Laquelle est-ce ?","o":["ق","ك","ف"],"c":0,"ex":"","arO":1,"a":1220},{"t":"qcm","q":"Que veut dire ce mot ?","o":["ici","non","lumière"],"c":0,"ex":"","big":"هُنَا"},{"t":"lis","w":{"ar":"كِتَاب","tr":"ki-tâb","fr":"livre","a":0,"v":"كِتَاب","dz":0},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"سَمَك","tr":"sa-mak","fr":"poisson","a":0,"v":"سَمَك","dz":0},"q":"Lis ce mot à voix haute"},{"t":"ass","ar":"قَلَم","tr":"qa-lam","fr":"stylo","q":"Écris « qalam » (stylo) : touche les lettres dans l’ordre de lecture"}]},{"id":"r8","e":"⏸️","n":"Le soukoun et la chadda","goal":"lire les consonnes sans voyelle et les consonnes doublées.","h":"<div class=\"card\"><h3><span class=\"n\">1</span>Le soukoun ـْ : pas de voyelle</h3><p>Un petit rond au-dessus de la lettre veut dire : <b>aucune voyelle</b>. La consonne ferme la syllabe.</p><div class=\"hxs\"><div class=\"hx\"><span lang=\"ar\">بَيْت</span><small>bay-t → bayt</small></div><div class=\"hx\"><span lang=\"ar\">مَكْتَب</span><small>mak-tab</small></div></div><p>Remarque : <span lang=\"ar\" class=\"ari\">ـَيْ</span> se lit <b>ay</b> et <span lang=\"ar\" class=\"ari\">ـَوْ</span> se lit <b>aw</b>.</p></div><div class=\"card\"><h3><span class=\"n\">2</span>La chadda ـّ : la lettre doublée</h3><p>Un petit « w » au-dessus de la lettre : on la prononce <b>deux fois</b>, en appuyant. La voyelle s’écrit avec la chadda.</p><div class=\"hxs\"><div class=\"hx\"><span lang=\"ar\">سُكَّر</span><small>souk-kar</small></div><div class=\"hx\"><span lang=\"ar\">حَمَّام</span><small>7am-mâm</small></div></div><p class=\"tip\">💡 La chadda change le sens : <span lang=\"ar\" class=\"ari\">دَرَسَ</span> (darasa) « il a étudié », <span lang=\"ar\" class=\"ari\">دَرَّسَ</span> (darrasa) « il a enseigné ».</p></div><div class=\"card\"><h3><span class=\"n\">3</span>Lecture guidée</h3>%READ%</div>","read":[{"ar":"بَيْت","tr":"bayt","fr":"maison","a":0,"v":"بَيْت","dz":0},{"ar":"بِنْت","tr":"bint","fr":"fille","a":0,"v":"بِنْت","dz":0},{"ar":"خُبْز","tr":"khoubz","fr":"pain","a":0,"v":"خُبْز","dz":0},{"ar":"مَكْتَب","tr":"mak-tab","fr":"bureau","a":0,"v":"مَكْتَب","dz":0},{"ar":"حَمَّام","tr":"7am-mâm","fr":"hammam, salle de bain","a":0,"v":"حَمَّام","dz":0},{"ar":"سُكَّر","tr":"souk-kar","fr":"sucre","a":0,"v":"سُكَّر","dz":0},{"ar":"مُدَرِّس","tr":"mou-dar-ris","fr":"enseignant","a":0,"v":"مُدَرِّس","dz":0},{"ar":"قِطّ","tr":"qiṭṭ","fr":"chat","a":0,"v":"قِطّ","dz":0}],"q":[{"t":"qcm","q":"Le petit rond ـْ sur une lettre veut dire…","o":["pas de voyelle","une voyelle longue","une lettre doublée"],"c":0,"ex":""},{"t":"qcm","q":"La chadda ـّ veut dire…","o":["la lettre est doublée","la lettre est muette","la voyelle est longue"],"c":0,"ex":""},{"t":"qcm","q":"Comment se lit ce mot ?","o":["souk-kar","sou-kar","sak-kar"],"c":0,"ex":"","big":"سُكَّر"},{"t":"qcm","q":"Comment se lit ce mot ?","o":["bayt","bît","ba-yit"],"c":0,"ex":"","big":"بَيْت"},{"t":"qcm","q":"Quelle écriture se lit « 7ammâm » ?","o":["حَمَّام","حَمَام","حَمَّم"],"c":0,"ex":"","arO":1},{"t":"lis","w":{"ar":"مَكْتَب","tr":"mak-tab","fr":"bureau","a":0,"v":"مَكْتَب","dz":0},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"مُدَرِّس","tr":"mou-dar-ris","fr":"enseignant","a":0,"v":"مُدَرِّس","dz":0},"q":"Lis ce mot à voix haute"},{"t":"ass","ar":"بِنْت","tr":"bint","fr":"fille","q":"Écris « bint » (fille) : touche les lettres dans l’ordre de lecture"}]},{"id":"r9","e":"☀️","n":"L’article ال : lettres solaires et lunaires","goal":"lire « le, la » devant n’importe quel mot.","h":"<div class=\"card\"><h3><span class=\"n\">1</span>ال = le, la, les</h3><p>L’article <b>ال</b> (al) se colle au début du mot : <span lang=\"ar\" class=\"ari\">بَاب</span> « une porte », <span lang=\"ar\" class=\"ari\">الْبَاب</span> « la porte ».</p></div><div class=\"card\"><h3><span class=\"n\">2</span>Lettres lunaires : on entend le l</h3><p>Devant 14 lettres, le l se prononce normalement. Le ل porte un soukoun : <span lang=\"ar\" class=\"ari\">الْقَمَر</span> = <b>al-qamar</b> (la lune).</p><p class=\"ari\" lang=\"ar\">ا ب ج ح خ ع غ ف ق ك م ه و ي</p></div><div class=\"card\"><h3><span class=\"n\">3</span>Lettres solaires : le l disparaît</h3><p>Devant les 14 autres, le l <b>ne se prononce pas</b> : la lettre suivante est doublée et porte une chadda. <span lang=\"ar\" class=\"ari\">الشَّمْس</span> = <b>ach-chams</b> (le soleil), pas « al-chams ».</p><p class=\"ari\" lang=\"ar\">ت ث د ذ ر ز س ش ص ض ط ظ ل ن</p><p class=\"tip\">💡 À l’écrit, c’est facile : s’il y a une <b>chadda</b> juste après ال, la lettre est solaire. Les solaires se prononcent toutes avec le bout de la langue près des dents.</p></div><div class=\"card\"><h3><span class=\"n\">4</span>Lecture guidée</h3>%READ%</div>","read":[{"ar":"الْقَمَر","tr":"al-qa-mar","fr":"la lune","a":0,"v":"الْقَمَر","dz":0},{"ar":"الْكِتَاب","tr":"al-ki-tâb","fr":"le livre","a":0,"v":"الْكِتَاب","dz":0},{"ar":"الْبَاب","tr":"al-bâb","fr":"la porte","a":0,"v":"الْبَاب","dz":0},{"ar":"الْوَلَد","tr":"al-wa-lad","fr":"le garçon","a":0,"v":"الْوَلَد","dz":0},{"ar":"الشَّمْس","tr":"ach-chams","fr":"le soleil","a":0,"v":"الشَّمْس","dz":0},{"ar":"النُّور","tr":"an-noûr","fr":"la lumière","a":0,"v":"النُّور","dz":0},{"ar":"السُّكَّر","tr":"as-souk-kar","fr":"le sucre","a":0,"v":"السُّكَّر","dz":0},{"ar":"الدَّار","tr":"ad-dâr","fr":"la maison","a":0,"v":"الدَّار","dz":0}],"q":[{"t":"tri","q":"Le l de ال se prononce-t-il ?","cats":["On entend « al » (lunaire)","Le l disparaît (solaire)"],"it":[["الْقَمَر",0],["الشَّمْس",1],["الْبَاب",0],["النُّور",1],["الدَّار",1],["الْكِتَاب",0],["السُّكَّر",1],["الْوَلَد",0]]},{"t":"qcm","q":"Comment se lit ce mot ?","o":["ach-chams","al-chams","a-chams"],"c":0,"ex":"","big":"الشَّمْس"},{"t":"qcm","q":"Comment se lit ce mot ?","o":["al-qamar","aq-qamar","al-amar"],"c":0,"ex":"","big":"الْقَمَر"},{"t":"qcm","q":"À l’écrit, comment reconnaître une lettre solaire après ال ?","o":["Elle porte une chadda","Le ل porte un soukoun","L’article disparaît"],"c":0,"ex":""},{"t":"qcm","q":"Comment se lit ce mot ?","o":["ad-dâr","al-dâr","a-dar"],"c":0,"ex":"","big":"الدَّار"},{"t":"lis","w":{"ar":"النُّور","tr":"an-noûr","fr":"la lumière","a":0,"v":"النُّور","dz":0},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"الْكِتَاب","tr":"al-ki-tâb","fr":"le livre","a":0,"v":"الْكِتَاب","dz":0},"q":"Lis ce mot à voix haute"}]},{"id":"r10","e":"🎀","n":"Les fins de mots : ة, ى et le tanwîn","goal":"lire correctement la fin des mots.","h":"<div class=\"card\"><h3><span class=\"n\">1</span>ة : le tâ marbouta</h3><p>Un ه avec deux points, uniquement en <b>fin de mot</b>. Il marque souvent le féminin. En fin de phrase, il se lit simplement <b>a</b> : <span lang=\"ar\" class=\"ari\">مَدْرَسَة</span> = madrasa (école).</p></div><div class=\"card\"><h3><span class=\"n\">2</span>ى : l’alif maqsoura</h3><p>Comme un ي <b>sans points</b>, en fin de mot. Il se lit <b>â</b>, comme un alif : <span lang=\"ar\" class=\"ari\">عَلَى</span> = 3alâ (sur).</p></div><div class=\"card\"><h3><span class=\"n\">3</span>Le tanwîn : -an, -in, -oun</h3><p>Une voyelle <b>doublée</b> en fin de mot ajoute un n :</p><div class=\"hxs\"><div class=\"hx\"><span lang=\"ar\">كِتَابًا</span><small>-an</small></div><div class=\"hx\"><span lang=\"ar\">كِتَابٍ</span><small>-in</small></div><div class=\"hx\"><span lang=\"ar\">كِتَابٌ</span><small>-oun</small></div></div><p>Le tanwîn -an s’écrit presque toujours sur un <b>alif qui ne se prononce pas</b> : <span lang=\"ar\" class=\"ari\">شُكْرًا</span> = choukran (merci).</p></div><div class=\"card\"><h3><span class=\"n\">4</span>Lecture guidée</h3>%READ%</div>","read":[{"ar":"مَدْرَسَة","tr":"mad-ra-sa","fr":"école","a":0,"v":"مَدْرَسَة","dz":0},{"ar":"جَدِيدَة","tr":"ja-dî-da","fr":"nouvelle","a":0,"v":"جَدِيدَة","dz":0},{"ar":"سَيَّارَة","tr":"say-yâ-ra","fr":"voiture","a":0,"v":"سَيَّارَة","dz":0},{"ar":"شُكْرًا","tr":"chouk-ran","fr":"merci","a":0,"v":"شُكْرًا","dz":0},{"ar":"عَفْوًا","tr":"3af-wan","fr":"de rien, pardon","a":0,"v":"عَفْوًا","dz":0},{"ar":"عَلَى","tr":"3a-lâ","fr":"sur","a":0,"v":"عَلَى","dz":0},{"ar":"مُسْتَشْفَى","tr":"mous-tach-fâ","fr":"hôpital","a":0,"v":"مُسْتَشْفَى","dz":0},{"ar":"كِتَابٌ","tr":"ki-tâ-boun","fr":"un livre","a":0,"v":"كِتَابٌ","dz":0}],"q":[{"t":"qcm","q":"En fin de phrase, ة se lit…","o":["a","t","h"],"c":0,"ex":"","big":"ة"},{"t":"qcm","q":"Dans عَلَى, la dernière lettre ى se lit…","o":["â, comme un alif","î","y"],"c":0,"ex":"","big":"عَلَى"},{"t":"qcm","q":"Comment se lit ce mot ?","o":["choukran","choukrâ","choukra"],"c":0,"ex":"Le ا final porte le tanwîn -an et ne se prononce pas.","big":"شُكْرًا"},{"t":"qcm","q":"Comment se lit ce mot ?","o":["kitâboun","kitâbou","kitâbân"],"c":0,"ex":"","big":"كِتَابٌ"},{"t":"qcm","q":"Que veut dire ce mot ?","o":["voiture","école","hôpital"],"c":0,"ex":"","big":"سَيَّارَة"},{"t":"lis","w":{"ar":"مَدْرَسَة","tr":"mad-ra-sa","fr":"école","a":0,"v":"مَدْرَسَة","dz":0},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"مُسْتَشْفَى","tr":"mous-tach-fâ","fr":"hôpital","a":0,"v":"مُسْتَشْفَى","dz":0},"q":"Lis ce mot à voix haute"},{"t":"ass","ar":"عَفْوًا","tr":"3af-wan","fr":"de rien","q":"Écris « 3afwan » (de rien) : touche les lettres dans l’ordre de lecture"}]},{"id":"r11","e":"✋","n":"La hamza ء et ses supports","goal":"reconnaître la hamza et lire les mots qui commencent par une voyelle.","h":"<div class=\"card\"><h3><span class=\"n\">1</span>Un petit coup de gorge</h3><p>La <b>hamza</b> <span lang=\"ar\" class=\"ari\">ء</span> est un petit arrêt de la voix, comme entre les deux « a » de « Ah ! Ah ! », ou dans « un·œuf » prononcé bien détaché. On la note <b>’</b> au milieu d’un mot.</p><p>Elle s’écrit rarement seule : elle « s’assoit » sur un support. En début de mot, toujours sur un alif.</p></div><div class=\"card\"><h3><span class=\"n\">2</span>Les supports</h3><table class=\"hk\"><tr><th>Écriture</th><th>Quand</th><th>Exemple</th></tr><tr><td lang=\"ar\" class=\"ari\">أ</td><td>hamza sur l’alif, avec a ou ou</td><td lang=\"ar\" class=\"ari\">أَب</td></tr><tr><td lang=\"ar\" class=\"ari\">إ</td><td>hamza sous l’alif, avec i</td><td lang=\"ar\" class=\"ari\">إِلَى</td></tr><tr><td lang=\"ar\" class=\"ari\">ؤ</td><td>sur un waw</td><td lang=\"ar\" class=\"ari\">سُؤَال</td></tr><tr><td lang=\"ar\" class=\"ari\">ئ</td><td>sur un ya sans points</td><td lang=\"ar\" class=\"ari\">بِئْر</td></tr><tr><td lang=\"ar\" class=\"ari\">ء</td><td>seule, souvent en fin de mot</td><td lang=\"ar\" class=\"ari\">مَاء</td></tr></table><p class=\"tip\">💡 Pour lire, pas besoin de connaître les règles du support : repère la hamza, marque un petit arrêt et lis la voyelle.</p><p><span lang=\"ar\" class=\"ari\">آ</span> (alif madda) = hamza + â long : <span lang=\"ar\" class=\"ari\">قُرْآن</span> = qour’ân.</p></div><div class=\"card\"><h3><span class=\"n\">3</span>Lecture guidée</h3>%READ%</div>","read":[{"ar":"أَب","tr":"ab","fr":"père","a":0,"v":"أَب","dz":0},{"ar":"أُمّ","tr":"oumm","fr":"mère","a":0,"v":"أُمّ","dz":0},{"ar":"أَهْلًا","tr":"ah-lan","fr":"bienvenue, salut","a":0,"v":"أَهْلًا","dz":0},{"ar":"إِلَى","tr":"i-lâ","fr":"vers, à","a":0,"v":"إِلَى","dz":0},{"ar":"سُؤَال","tr":"sou-’âl","fr":"question","a":0,"v":"سُؤَال","dz":0},{"ar":"بِئْر","tr":"bi’r","fr":"puits","a":0,"v":"بِئْر","dz":0},{"ar":"مَاء","tr":"mâ’","fr":"eau","a":0,"v":"مَاء","dz":0},{"ar":"سَمَاء","tr":"sa-mâ’","fr":"ciel","a":0,"v":"سَمَاء","dz":0},{"ar":"قُرْآن","tr":"qour-’ân","fr":"Coran","a":0,"v":"قُرْآن","dz":0}],"q":[{"t":"qcm","q":"La hamza ء est…","o":["un petit arrêt de la voix","un h soufflé","une voyelle longue"],"c":0,"ex":""},{"t":"qcm","q":"La hamza <b>sous</b> l’alif (إ) va avec la voyelle…","o":["i","a","ou"],"c":0,"ex":"","big":"إ"},{"t":"qcm","q":"Comment se lit ce mot ?","o":["oumm","amm","oum"],"c":0,"ex":"","big":"أُمّ"},{"t":"qcm","q":"Comment se lit آ ?","o":["’â : hamza + a long","î","deux alifs séparés"],"c":0,"ex":"","big":"آ"},{"t":"qcm","q":"Que veut dire ce mot ?","o":["bienvenue, salut","merci","père"],"c":0,"ex":"","big":"أَهْلًا"},{"t":"lis","w":{"ar":"سُؤَال","tr":"sou-’âl","fr":"question","a":0,"v":"سُؤَال","dz":0},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"سَمَاء","tr":"sa-mâ’","fr":"ciel","a":0,"v":"سَمَاء","dz":0},"q":"Lis ce mot à voix haute"},{"t":"ass","ar":"أَب","tr":"ab","fr":"père","q":"Écris « ab » (père) : touche les lettres dans l’ordre de lecture"}]},{"id":"r12","e":"👓","n":"Lire sans voyelles : panneaux et enseignes","goal":"lire de vrais mots écrits sans voyelles, comme dans la rue.","h":"<div class=\"card\"><h3><span class=\"n\">1</span>La vraie vie</h3><p>Sur les panneaux, les enseignes et les téléphones, les voyelles courtes, le soukoun et la chadda ne sont <b>presque jamais écrits</b>. Le lecteur les devine. Ça s’apprend, avec quatre réflexes :</p><ol><li>Les <b>voyelles longues</b> ا و ي sont toujours écrites : repère-les en premier.</li><li><b>ال</b> au début = « le, la ».</li><li><b>ة</b> à la fin = « -a », et <b>ية</b> = « -iyya ».</li><li>Pour le reste, on s’appuie sur les mots qu’on connaît déjà.</li></ol><p class=\"tip\">💡 Dans les exercices, la première aide <b>remet les voyelles</b>. Essaie d’abord sans.</p></div><div class=\"card\"><h3><span class=\"n\">2</span>Lecture guidée : villes et enseignes</h3><p>Pour les villes, l’audio fait entendre le nom <b>en darija</b>, qui est souvent plus court que la lecture en arabe standard (الجزائر : al-jazâ’ir en standard, Dzayer en darija).</p>%READ%</div>","read":[{"ar":"الجزائر","tr":"al-ja-zâ-’ir","fr":"l’Algérie, Alger","a":308,"v":"الْجَزَائِر","dz":1},{"ar":"وهران","tr":"wah-rân","fr":"Oran","a":309,"v":"وَهْرَان","dz":1},{"ar":"قسنطينة","tr":"qa-san-ṭî-na","fr":"Constantine","a":310,"v":"قَسَنْطِينَة","dz":1},{"ar":"عنابة","tr":"3an-nâ-ba","fr":"Annaba","a":311,"v":"عَنَّابَة","dz":1},{"ar":"تلمسان","tr":"ti-lim-sân","fr":"Tlemcen","a":312,"v":"تِلِمْسَان","dz":1},{"ar":"مطعم","tr":"maṭ-3am","fr":"restaurant","a":0,"v":"مَطْعَم","dz":0},{"ar":"صيدلية","tr":"ṣay-da-liy-ya","fr":"pharmacie","a":0,"v":"صَيْدَلِيَّة","dz":0},{"ar":"مخبزة","tr":"makh-ba-za","fr":"boulangerie","a":0,"v":"مَخْبَزَة","dz":0},{"ar":"شارع","tr":"châ-ri3","fr":"rue, avenue","a":296,"v":"شَارِع","dz":1},{"ar":"بريد","tr":"ba-rîd","fr":"poste","a":0,"v":"بَرِيد","dz":0}],"q":[{"t":"qcm","q":"Qu’est-ce qui est presque toujours écrit, même sans voyelles ?","o":["Les voyelles longues ا و ي","Les voyelles courtes","La chadda"],"c":0,"ex":""},{"t":"qcm","q":"Sur une enseigne, que veut dire ce mot ?","o":["pharmacie","boulangerie","restaurant"],"c":0,"ex":"","big":"صيدلية"},{"t":"qcm","q":"Comment se lit ce mot ?","o":["maṭ3am","maṭâ3im","mouṭ3im"],"c":0,"ex":"","big":"مطعم","h":"Il n’y a aucune voyelle longue : toutes les voyelles sont courtes."},{"t":"qcm","q":"Quelle ville est écrite ici ?","o":["Oran","Annaba","Tlemcen"],"c":0,"ex":"","big":"وهران"},{"t":"lis","w":{"ar":"الجزائر","tr":"al-ja-zâ-’ir","fr":"l’Algérie, Alger","a":308,"v":"الْجَزَائِر","dz":1},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"قسنطينة","tr":"qa-san-ṭî-na","fr":"Constantine","a":310,"v":"قَسَنْطِينَة","dz":1},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"مخبزة","tr":"makh-ba-za","fr":"boulangerie","a":0,"v":"مَخْبَزَة","dz":0},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"شارع","tr":"châ-ri3","fr":"rue, avenue","a":296,"v":"شَارِع","dz":1},"q":"Lis ce mot à voix haute"}]},{"id":"r13","e":"🏁","n":"Bilan : lire le darija écrit","goal":"lire les mots du cours de darija tels que les Algériens les écrivent.","h":"<div class=\"card\"><h3><span class=\"n\">1</span>Le darija à l’écrit</h3><p>Le darija n’a pas d’orthographe officielle. Les Algériens l’écrivent <b>comme ils le prononcent</b>, sans voyelles. Le même mot peut donc avoir deux ou trois écritures : <span lang=\"ar\" class=\"ari\">يما</span> ou <span lang=\"ar\" class=\"ari\">يمّا</span> (yemma).</p><p>Tu as tous les outils : repère les voyelles longues, devine le reste, et vérifie avec l’audio. Ces mots viennent tous du cours de darija.</p></div><div class=\"card\"><h3><span class=\"n\">2</span>Lecture guidée</h3>%READ%</div>","read":[{"ar":"واش راك؟","tr":"wach rak ?","fr":"comment vas-tu ?","a":2,"v":"واش راك؟","dz":1},{"ar":"لاباس","tr":"la-bas","fr":"ça va","a":3,"v":"لاباس","dz":1},{"ar":"صحا","tr":"ṣa-7a","fr":"merci, bravo","a":8,"v":"صحا","dz":1},{"ar":"بزّاف","tr":"bez-zaf","fr":"beaucoup","a":146,"v":"بزّاف","dz":1},{"ar":"خبز","tr":"khobz","fr":"pain","a":247,"v":"خبز","dz":1},{"ar":"شمس","tr":"chems","fr":"soleil","a":335,"v":"شمس","dz":1},{"ar":"يمّا","tr":"yem-ma","fr":"maman","a":96,"v":"يمّا","dz":1},{"ar":"قهوة","tr":"qah-wa","fr":"café","a":266,"v":"قهوة","dz":1},{"ar":"حليب","tr":"7lib","fr":"lait","a":249,"v":"حليب","dz":1},{"ar":"بالسلامة","tr":"bslama","fr":"au revoir","a":23,"v":"بالسلامة","dz":1},{"ar":"حانوت","tr":"7a-nout","fr":"boutique, épicerie","a":288,"v":"حانوت","dz":1}],"q":[{"t":"qcm","q":"Écoute et choisis l’écriture","o":["بزّاف","بصح","بابا"],"c":0,"ex":"","arO":1,"a":146},{"t":"qcm","q":"Écoute et choisis l’écriture","o":["حليب","خبز","حانوت"],"c":0,"ex":"","arO":1,"a":249},{"t":"qcm","q":"Écoute et choisis l’écriture","o":["لاباس","بالسلامة","صحا"],"c":0,"ex":"","arO":1,"a":3},{"t":"qcm","q":"Écoute et choisis l’écriture","o":["قهوة","شمس","يمّا"],"c":0,"ex":"","arO":1,"a":266},{"t":"lis","w":{"ar":"واش راك؟","tr":"wach rak ?","fr":"comment vas-tu ?","a":2,"v":"واش راك؟","dz":1},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"بالسلامة","tr":"bslama","fr":"au revoir","a":23,"v":"بالسلامة","dz":1},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"حانوت","tr":"7a-nout","fr":"boutique, épicerie","a":288,"v":"حانوت","dz":1},"q":"Lis ce mot à voix haute"},{"t":"lis","w":{"ar":"شمس","tr":"chems","fr":"soleil","a":335,"v":"شمس","dz":1},"q":"Lis ce mot à voix haute"}]}];
// ===== Cours « Lire l'arabe » : navigation, aides à la lecture, exercices =====
const $=id=>document.getElementById(id);
const mel=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const ld=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))||d}catch(e){return d}};
const sv=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}};
const esc=s=>String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/"/g,"&quot;");
const hash=s=>{let h=5381;for(let i=0;i<s.length;i++)h=((h<<5)+h+s.charCodeAt(i))|0;return (h>>>0).toString(36)};

// ---------- Leçons et outils ----------
const L=LES.slice();L.forEach((l,i)=>l.no=i+1);
L.push({id:"lettres",custom:1,e:"📋",n:"Les 28 lettres"});
L.push({id:"revision",custom:1,e:"🔁",n:"Révision du jour"});
const NL=LES.length;
const AR=s=>String(s).replace(/[\u0600-\u06FF](?:[\u0600-\u06FF\s]*[\u0600-\u06FF])?/g,x=>`<bdi class="nw" lang="ar">${x}</bdi>`);

// ---------- Écriture arabe ----------
const HAR=/[ً-ْٰ]/;
const clusters=w=>{const r=[];for(const c of w){if(HAR.test(c)&&r.length)r[r.length-1]+=c;else if(c!==" "&&c!=="؟")r.push(c)}return r};
const SND=(a,lab)=>a?`<button class="snd" type="button" data-a="${a}" aria-label="${esc(lab)}">🔊</button>`:"";
const AL=([l,nom,son,nc,ar,tr,fr,an,ea])=>{const z="‍",f=nc?[l,l,z+l,z+l]:[l,l+z,z+l+z,z+l];
 return `<div class="alc${nc?" nc":""}"><div class="alh"><span class="all" lang="ar">${l}</span><div><b>${nom}</b>${nc?" ⛔":""}<em>${son}</em></div>${SND(an,"Écouter le nom de la lettre "+nom)}</div>
 <div class="alf" lang="ar">${f.map((x,i)=>`<span><i>${x}</i><small>${["isolée","début","milieu","fin"][i]}</small></span>`).join("")}</div>
 <div class="alx"><span class="ar" lang="ar">${ar}</span> <b>${tr}</b> <em>${fr}</em>${SND(ea,"Écouter le mot d’exemple "+tr)}</div></div>`};
const letterCards=s=>`<div class="alg">${[...s].map(c=>AL(ALPHA["ابتثجحخدذرزسشصضطظعغفقكلمنهوي".indexOf(c)])).join("")}</div>`;

// Carte de lecture avec trois aides : lettre par lettre, début, réponse
let RW={},rwn=0;
function reader(w,quiz){const k="w"+(++rwn);RW[k]={w,n:0,quiz};
 const parts=clusters(w.v),first=w.tr.split("-")[0];
 return `<div class="rw" id="${k}"><div class="rwa" lang="ar" dir="rtl">${w.ar}</div>
 <div class="rwh" data-h="1" hidden><span class="rwl">${w.v!==w.ar?"Avec les voyelles, lettre par lettre :":"Lettre par lettre :"}</span><div class="rwc" lang="ar" dir="rtl">${parts.map(p=>`<span>${p}</span>`).join("")}</div></div>
 <div class="rwh" data-h="2" hidden><span class="rwl">Ça commence par :</span> <b>${esc(first)}</b>${w.tr.includes("-")?" …":""}</div>
 <div class="rwh rwr" data-h="3" hidden><b>${esc(w.tr.replace(/-/g,"·"))}</b>${w.fr?` <span>${esc(w.fr)}</span>`:""}${SND(w.a,"Écouter "+w.tr)}${w.a&&w.dz?' <small class="dzn">audio en darija</small>':""}</div>
 <div class="rwb">${parts.length>1||w.v!==w.ar?`<button type="button" data-rw="1">🔤 Lettre par lettre</button>`:""}${w.tr.includes("-")?`<button type="button" data-rw="2">💡 Le début</button>`:""}<button type="button" data-rw="3">👁️ ${quiz?"Vérifier":"Réponse"}</button></div></div>`}
document.addEventListener("click",e=>{const b=e.target.closest&&e.target.closest("[data-rw]");if(!b)return;
 const box=b.closest(".rw"),st=RW[box.id],h=+b.dataset.rw;
 box.querySelector(`[data-h="${h}"]`).hidden=false;b.disabled=true;
 if(h<3)st.n++;else{box.querySelectorAll("[data-rw]").forEach(x=>x.disabled=true);if(st.quiz)selfGrade(st)}});

// ---------- État ----------
let cur=0,mode="cours",qi=0,score=0,qs=[],fait=[],miss=[],kind="quiz",pend=[],cho=[],tri=[];
let res=ld("ar_res",{}),SR=ld("ar_sr",{});
{const k=L.findIndex(l=>l.id==ld("ar_last",""));if(k>0)cur=k}
const INT=[0,1,3,7,14,30];
const qkey=q=>hash(q.t+"|"+q.q+"|"+(q.t=="qcm"?q.o[0]+(q.big||"")+(q.a||""):q.t=="lis"?q.w.ar:q.t=="ass"?q.ar:q.it.map(x=>x[0]).join("")));
let QMAP=null;const allQ=()=>{if(!QMAP){QMAP={};LES.forEach(l=>l.q.forEach(q=>QMAP[qkey(q)]=q))}return QMAP};
function rec(q,ok){const k=qkey(q),s=SR[k]||{b:0,d:0};if(ok){s.b=Math.min(5,s.b+1);s.d=Date.now()+INT[s.b]*864e5}else{s.b=1;s.d=Date.now()}SR[k]=s;sv("ar_sr",SR)}
const dueKeys=()=>{const m=allQ(),n=Date.now();return Object.keys(SR).filter(k=>m[k]&&SR[k].d<=n)};

// ---------- Menu ----------
function menu(){let h=`<div class="ch"><span>📖 Apprendre à lire</span><b>${LES.filter(l=>res[l.id]!=null).length}/${NL}</b></div>`;const du=dueKeys().length;
 L.forEach((l,i)=>{if(i==NL)h+=`<div class="ch"><span>🧰 Outils</span></div>`;
  const badge=l.id=="revision"&&du?`<span class="sc">${du}</span>`:res[l.id]!=null?`<span class="sc">✓ ${res[l.id]}%</span>`:"";
  h+=`<button class="${i==cur?"on":""}"${i==cur?' aria-current="page"':""} onclick="go(${i})"><span>${l.e}</span><span class="lt">${l.no?l.no+". ":""}${AR(l.n)}</span>${badge}</button>`});
 $("menu").innerHTML=h;const n=LES.filter(l=>res[l.id]!=null).length,p=Math.round(100*n/NL);
 $("gp").style.width=p+"%";$("gl").textContent=n+" / "+NL+" leçons · "+p+" %";$("pbar").setAttribute("aria-valuenow",p)}
function go(i){cur=i;mode="cours";kind="quiz";sv("ar_last",L[i].id);$("menu").classList.remove("open");$("ov").classList.remove("open");scrollTo(0,0);draw()}
const chip=l=>l.no?`<div class="chip">📖 Lire l’arabe · Leçon ${l.no} sur ${NL}</div><br>`:"";
function nav(extra){return `<div class="nav"><button ${cur?"":"disabled"} onclick="go(${cur-1})">← Précédent</button>${extra}</div>`}
function draw(){menu();RW={};const l=L[cur];document.title=(l.no?"Leçon "+l.no+" : ":"")+l.n+" – Lire l’arabe";
 if(mode=="quiz")return drawQ();if(mode=="fin")return drawEnd();
 if(l.custom){$("main").innerHTML=`<h2 class="t">${l.e} ${l.n}</h2>`+PAGES[l.id]()+nav(cur<L.length-1?`<button onclick="go(${cur+1})">Suivant →</button>`:"");return}
 let h=l.h.replace("%LETTERS%",l.L?letterCards(l.L):"").replace("%READ%",`<div class="rws">${l.read.map(w=>reader(w,0)).join("")}</div>`);
 $("main").innerHTML=`<h2 class="t">${chip(l)}${l.e} ${AR(l.n)}</h2><div class="goal">🎯 Objectif : ${l.goal}</div>${h}
 ${nav(`<button onclick="start()">🎮 Passer aux activités →</button>`)}`}

// ---------- Exercices ----------
function begin(list,k){qs=list;qi=0;score=0;miss=[];kind=k;fait=qs.map(()=>false);mode="quiz";scrollTo(0,0);draw()}
function start(){begin(mel(L[cur].q),"quiz")}
function retry(){begin(miss.slice(),"retry")}
function revStart(){const m=allQ();begin(dueKeys().sort((a,b)=>SR[a].d-SR[b].d).slice(0,10).map(k=>m[k]),"review")}
function drawQ(){RW={};const q=qs[qi],pc=Math.round(100*qi/qs.length);let body="",top="";
 if(q.a)top+=`<p class="lis-a">${SND(q.a,"Écouter")} <span>Touche 🔊 pour écouter</span></p>`;
 if(q.big)top+=`<div class="qbig" lang="ar" dir="rtl">${q.big}</div>`;
 if(q.t=="qcm"){pend=mel(q.o);body=pend.map((o,i)=>`<button class="opt${q.arO?" opa":""}"${q.arO?' lang="ar"':""} onclick="pick(${i})">${o}</button>`).join("")}
 else if(q.t=="lis")body=reader(q.w,1)+`<div id="sg"></div>`;
 else if(q.t=="ass"){pend=mel(clusters(q.ar).map((c,i)=>({c,i})));cho=[];
  body=`<div class="asw" lang="ar" dir="rtl" id="asw"></div><div class="ans asr" id="ans" dir="rtl"></div><div class="pool asr" id="pool" dir="rtl"></div><button onclick="chk()">Vérifier ✔</button> <button onclick="clr()">Effacer</button>`}
 else if(q.t=="tri"){tri=q.it.map(()=>null);body=`<div class="tri">${q.it.map((x,i)=>`<div class="trr"><span lang="ar">${x[0]}</span><div>${q.cats.map((c,j)=>`<button type="button" data-t="${i}" data-c="${j}" onclick="tsel(${i},${j})">${c}</button>`).join("")}</div></div>`).join("")}</div><button onclick="tchk()">Vérifier ✔</button>`}
 if(q.h)body+=` <button id="hb" onclick="this.outerHTML='<p class=tip>💡 '+this.dataset.h+'</p>'" data-h="${esc(q.h)}">💡 Indice</button>`;
 const t=kind=="review"?"🔁 Révision du jour":kind=="retry"?"🔁 Mes erreurs":L[cur].e+" "+AR(L[cur].n);
 $("main").innerHTML=`<h2 class="t">${kind=="quiz"?chip(L[cur]):""}${t}</h2>
 <div class="bar" role="progressbar" aria-label="Progression" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pc}"><i style="width:${pc}%"></i></div><p>Question ${qi+1} / ${qs.length} · Score : ${score}</p>
 <div class="card"><h3>${q.q}</h3>${top}${body}<div id="fb" aria-live="polite"></div></div>
 <div class="nav"><button onclick="go(${cur})">${kind=="review"?"← Retour":"📖 Relire la leçon"}</button><button id="nx" disabled onclick="next()">Suivant →</button></div>`;
 if(q.t=="ass")ord()}
function ord(){$("asw").textContent=cho.map(x=>x.c).join("")||"…";
 $("ans").innerHTML=cho.map((x,i)=>`<button lang="ar" onclick="un(${i})">${x.c}</button>`).join("");
 $("pool").innerHTML=pend.map((x,i)=>`<button lang="ar" onclick="ad(${i})">${x.c}</button>`).join("")}
function clr(){pend=mel(clusters(qs[qi].ar).map((c,i)=>({c,i})));cho=[];ord()}
function ad(i){cho.push(pend.splice(i,1)[0]);ord()}
function un(i){pend.push(cho.splice(i,1)[0]);ord()}
function chk(){const q=qs[qi];if(!cho.length)return;$("pool").style.display="none";fin(cho.map(x=>x.c).join("")==clusters(q.ar).join(""))}
function tsel(i,j){tri[i]=j;document.querySelectorAll(`[data-t="${i}"]`).forEach(b=>b.classList.toggle("sel",+b.dataset.c==j))}
function tchk(){const q=qs[qi];if(tri.some(x=>x==null)){$("fb").innerHTML=`<p class="hint">Range d’abord toutes les lettres.</p>`;return}
 let ok=true;q.it.forEach((x,i)=>{const b=document.querySelector(`[data-t="${i}"][data-c="${tri[i]}"]`),g=tri[i]==x[1];if(!g)ok=false;b.classList.add(g?"ok":"ko");if(!g)document.querySelector(`[data-t="${i}"][data-c="${x[1]}"]`).classList.add("ok")});
 fin(ok)}
function pick(i){const q=qs[qi],ok=pend[i]==q.o[0];
 document.querySelectorAll(".opt").forEach((b,j)=>{b.disabled=true;if(pend[j]==q.o[0])b.classList.add("ok");else if(j==i)b.classList.add("ko")});fin(ok)}
function selfGrade(st){$("sg").innerHTML=`<p class="hint">Tu avais bien lu ?</p><div class="sgb"><button onclick="sgr(1)">✅ Oui, je l’avais lu</button><button onclick="sgr(0)">❌ Pas encore</button></div>`;$("sg").dataset.n=st.n}
function sgr(ok){const n=+$("sg").dataset.n;$("sg").innerHTML="";fin(!!ok,ok?(n?"Lu avec "+n+" aide"+(n>1?"s":"")+".":"Lu sans aide."):"Ce mot reviendra dans ta révision du jour.")}
function fin(ok,msg){const q=qs[qi];
 if(!fait[qi]){fait[qi]=true;if(ok)score++;else miss.push(q);if(kind!="retry")rec(q,ok)}
 let rep="";if(!ok){rep=q.t=="qcm"?q.o[0]:q.t=="ass"?`<span lang="ar" class="ari">${q.ar}</span> (${q.tr.replace(/-/g,"")})`:""}
 const lbl=q.t=="lis"?(ok?"✅ ":"📌 "):ok?"✅ Bravo. ":"❌ Pas tout à fait. ";
 $("fb").innerHTML=`<div class="fb ${ok?"ok":"ko"}">${lbl}${rep?"Bonne réponse : "+(q.arO?`<span lang="ar" class="ari">${rep}</span>`:rep)+" ":""}${msg||""}${q.ex?" "+q.ex:""}</div>`+(!ok&&q.t!="lis"?`<p><button onclick="drawQ()">🔄 Réessayer</button></p>`:"");
 $("nx").disabled=false;$("nx").textContent=qi==qs.length-1?"Voir mon score 🎉":"Suivant →";
 document.querySelectorAll("#main .card button:not(.snd)").forEach(b=>{if(!b.textContent.includes("Réessayer"))b.disabled=true})}
function next(){if(qi<qs.length-1){qi++;drawQ()}else{mode="fin";if(kind=="quiz"){res[L[cur].id]=Math.round(100*score/qs.length);sv("ar_res",res)}scrollTo(0,0);draw()}}
function drawEnd(){const p=Math.round(100*score/qs.length),s=p>=90?"🌟🌟🌟":p>=60?"🌟🌟":"🌟";
 const again=kind=="review"?"":`<button onclick="start()">🔄 Nouvel essai</button>`;
 const back=kind=="review"?`<button onclick="go(${cur})">← Retour à la révision</button>`:`<button onclick="go(${cur})">📖 Relire la leçon</button><button ${cur<L.length-1?"":"disabled"} onclick="go(${cur+1})">Suivant →</button>`;
 $("main").innerHTML=`<h2 class="t">${kind=="review"?"🔁 Révision du jour":L[cur].e+" Résultat"}</h2><div class="card"><div class="big">${s}</div>
 <h3 style="text-align:center">${score} / ${qs.length} (${p} %)</h3>
 <p style="text-align:center">${p>=90?"Excellent, tu sais lire cette étape 🎉":p>=60?"Bien joué. Encore un essai pour viser les 3 étoiles.":"Relis la leçon avec les aides, puis réessaie."}</p></div>
 <div class="nav">${again}${miss.length?`<button onclick="retry()">🔁 Refaire mes erreurs (${miss.length})</button>`:""}${back}</div>`}

// ---------- Pages outils ----------
const PAGES={
 lettres(){return `<div class="card"><h3>L’alphabet complet</h3><p>Les 28 lettres dans l’ordre de l’alphabet, avec leurs 4 formes. ⛔ = ne s’attache pas à la lettre suivante. Le premier 🔊 dit le nom de la lettre, le second le mot d’exemple (en darija).</p>${letterCards("ابتثجحخدذرزسشصضطظعغفقكلمنهوي")}</div>`},
 revision(){const m=allQ(),now=Date.now(),ks=Object.keys(SR).filter(k=>m[k]),due=ks.filter(k=>SR[k].d<=now).length,mast=ks.filter(k=>SR[k].b>=5).length;
  const fut=ks.filter(k=>SR[k].d>now).map(k=>SR[k].d).sort((a,b)=>a-b)[0];let nx="";
  if(!due&&fut){const j=Math.max(1,Math.ceil((fut-now)/864e5));nx="Prochaine révision dans "+j+" jour"+(j>1?"s":"")+"."}
  return `<div class="card"><h3>Comment ça marche</h3><p>Chaque exercice réussi revient après 1, 3, 7, 14 puis 30 jours. Une erreur, ou un mot que tu n’avais pas su lire, le ramène à aujourd’hui.</p></div>
  <div class="card"><div class="stats"><div><b>${ks.length}</b><span>exercices vus</span></div><div><b>${due}</b><span>à réviser</span></div><div><b>${mast}</b><span>maîtrisés</span></div></div>
  ${due?`<p><button onclick="revStart()">▶️ Commencer (${Math.min(10,due)} exercices)</button></p>`:`<p>${ks.length?"Rien à réviser aujourd’hui. "+nx:"Fais d’abord quelques leçons : les exercices apparaîtront ici."}</p>`}</div>`}
};

// ---------- Démarrage ----------
$("burger").onclick=()=>{const o=$("menu").classList.toggle("open");$("ov").classList.toggle("open");$("burger").setAttribute("aria-expanded",o)};
$("ov").onclick=()=>{$("menu").classList.remove("open");$("ov").classList.remove("open");$("burger").setAttribute("aria-expanded","false")};
let dp=null;
addEventListener("beforeinstallprompt",e=>{e.preventDefault();dp=e;$("inst").hidden=false});
$("inst").onclick=()=>{if(dp){dp.prompt();dp=null;$("inst").hidden=true}};
if("serviceWorker" in navigator&&/^https?:$/.test(location.protocol))navigator.serviceWorker.register("sw.js").catch(()=>{});
draw();

// ---------- Audio ----------
let SNDP=null,SNDB=null;
document.addEventListener("click",e=>{const b=e.target.closest&&e.target.closest(".snd");if(!b)return;e.preventDefault();e.stopPropagation();
 if(SNDP){SNDP.pause();SNDP=null}if(SNDB)SNDB.classList.remove("on");
 const a=new Audio("audio/"+String(b.dataset.a).padStart(3,"0")+".mp3");SNDP=a;SNDB=b;b.classList.add("on");
 const off=()=>{b.classList.remove("on");if(SNDP===a)SNDP=null};a.onended=off;a.onerror=off;
 const p=a.play();if(p&&p.catch)p.catch(off)});
